// Captur8 — normaliza o payload cru do formulario antes de gravar.
// Modo do no: "Run Once for All Items".

const soDigitos = (texto) => String(texto ?? '').replace(/D/g, '');

// Telefone BR: 10 digitos NAO significa fixo. Antes do nono digito o celular
// tinha 8 digitos e comecava em 6, 7, 8 ou 9 (fixo comeca em 2 a 5).
// Classificar antes de descartar: a regra ingenua joga fora numero bom.
function normalizarTelefone(bruto) {
  let d = soDigitos(bruto);
  if (d.startsWith('55') && d.length > 11) d = d.slice(2);
  if (d.length < 10) return { telefone: d, tipo: 'invalido' };

  const ddd = d.slice(0, 2);
  const assinante = d.slice(2);

  if (Number(ddd) < 11) return { telefone: d, tipo: 'invalido' };
  if (assinante.length === 8 && /^[6-9]/.test(assinante)) {
    return { telefone: ddd + '9' + assinante, tipo: 'celular' };   // formato antigo
  }
  if (assinante.length === 8) return { telefone: d, tipo: 'fixo' }; // fixo tem WhatsApp
  if (assinante.length === 9) return { telefone: d, tipo: 'celular' };
  return { telefone: d, tipo: 'invalido' };
}

const saida = [];

for (const item of $input.all()) {
  // No no Webhook, o que o cliente mandou chega dentro de "body".
  const corpo = item.json.body ?? item.json;
  const { telefone, tipo } = normalizarTelefone(corpo.telefone ?? corpo.phone);
  const email = String(corpo.email ?? '').trim().toLowerCase();

  saida.push({
    json: {
      nome: String(corpo.nome ?? corpo.name ?? '').trim(),
      email,
      telefone,
      tipo_telefone: tipo,
      origem: corpo.origem ?? corpo.utm_source ?? 'desconhecida',
      mensagem: String(corpo.mensagem ?? '').trim(),
      recebido_em: new Date().toISOString(),
      // Chave de idempotencia: se o formulario disparar duas vezes, da pra
      // reconhecer o duplicado depois sem depender do horario.
      chave: (email || telefone || 'sem-chave'),
    },
  });
}

return saida;
